//! Wolfram two-step transient-adjoint replay.
//!
//! The fixture (`fixtures/transient_adjoint_golden.json`, generated by
//! `fixtures/transient_adjoint.wls` at 50-digit precision) carries the
//! closed-form backward sweep for a two-step trajectory with one BDF history
//! block — the same fixture shape as the frozen PC-fan regression. This test
//! replays it through the production `solve_transient_adjoint` path (GMRES
//! inner solves included), so the golden checks the solver, not just the
//! fixture arithmetic. No live engine needed per commit.

use serde::Deserialize;
use sonium_solvers_time_integration::{
    TransientAdjointConfig, TransientAdjointCsr, TransientAdjointStep, TransientHistoryJacobian,
    solve_transient_adjoint,
};

const GOLDEN: &str = include_str!("../fixtures/transient_adjoint_golden.json");

#[derive(Debug, Deserialize)]
struct Golden {
    schema_version: u32,
    case_id: String,
    lambda_1: Vec<f64>,
    lambda_0: Vec<f64>,
    design_gradient: Vec<f64>,
    tolerances: Tolerances,
}

#[derive(Debug, Deserialize)]
struct Tolerances {
    adjoint_abs: f64,
    gradient_abs: f64,
}

fn csr(values: &[Vec<f64>]) -> TransientAdjointCsr {
    TransientAdjointCsr::from_dense(values).expect("valid fixture matrix")
}

#[test]
fn wolfram_two_step_adjoint_replays_through_production_path() {
    let golden: Golden = serde_json::from_str(GOLDEN).expect("parse golden");
    assert_eq!(golden.schema_version, 1);
    assert_eq!(golden.case_id, "solvers.transient-adjoint-two-step.v1");

    let steps = vec![
        TransientAdjointStep {
            state_jacobian: csr(&[vec![2.0, 0.0], vec![0.0, 3.0]]),
            state_residual: vec![0.0, 0.0],
            history_jacobians: vec![],
            residual_design_jacobian: vec![vec![1.0], vec![2.0]],
            objective_state_gradient: vec![1.0, 2.0],
            objective_design_gradient: vec![0.1],
        },
        TransientAdjointStep {
            state_jacobian: csr(&[vec![2.0, 0.0], vec![0.0, 3.0]]),
            state_residual: vec![0.0, 0.0],
            history_jacobians: vec![TransientHistoryJacobian {
                previous_step: 0,
                matrix: csr(&[vec![0.5, 0.0], vec![0.0, 1.0]]),
            }],
            residual_design_jacobian: vec![vec![2.0], vec![1.0]],
            objective_state_gradient: vec![3.0, 4.0],
            objective_design_gradient: vec![0.2],
        },
    ];
    let report =
        solve_transient_adjoint(&TransientAdjointConfig::default(), &steps).expect("adjoint solve");
    assert!(report.converged);
    for (got, expected) in report.adjoints[1].iter().zip(&golden.lambda_1) {
        assert!((got - expected).abs() < golden.tolerances.adjoint_abs);
    }
    for (got, expected) in report.adjoints[0].iter().zip(&golden.lambda_0) {
        assert!((got - expected).abs() < golden.tolerances.adjoint_abs);
    }
    for (got, expected) in report.design_gradient.iter().zip(&golden.design_gradient) {
        assert!((got - expected).abs() < golden.tolerances.gradient_abs);
    }
}
